<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';
function formatH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Die Formatebibliothek ist Coaches vorbehalten.');}
$db=coachingDatabase();$coach=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$visibility=['privat'=>'Nur für mich','ausgewaehlte_coaches'=>'Ausgewählte Coaches','alle_coaches'=>'Alle Coaches'];$error='';$notice=isset($_GET['saved'])?'Eintrag gespeichert.':'';
$q=$db->query('SELECT id,name FROM coaching_format_kategorien ORDER BY name');$categories=$q->fetchAll(PDO::FETCH_ASSOC);
$values=['id'=>0,'titel'=>'','kategorie_id'=>null,'kategorie'=>'','kurzbeschreibung'=>'','ziel'=>'','ablauf'=>'','dauer_minuten'=>'','materialien'=>'','hinweise'=>'','quellen'=>'','tags'=>'','freigabe'=>'privat'];$selected=[];
$q=$db->query("SELECT id,vorname,nachname FROM benutzer WHERE aktiv=1 AND rolle='coach' ORDER BY nachname,vorname");$coaches=$q->fetchAll(PDO::FETCH_ASSOC);
if(isset($_GET['edit'])){$edit=filter_var($_GET['edit'],FILTER_VALIDATE_INT);if($edit!==false&&$edit>0){$q=$db->prepare('SELECT * FROM coaching_formate WHERE id=:id AND coach_benutzer_id=:owner');$q->execute(['id'=>$edit,'owner'=>$coach]);$row=$q->fetch(PDO::FETCH_ASSOC);if($row){$values=$row;$values['id']=(int)$row['id'];$q=$db->prepare('SELECT coach_benutzer_id FROM coaching_format_freigaben WHERE format_id=:id');$q->execute(['id'=>$edit]);$selected=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}}}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
$id=(int)($_POST['id']??0);$input=[];foreach(['titel','kurzbeschreibung','ziel','ablauf','materialien','hinweise','quellen','tags'] as $key)$input[$key]=trim((string)($_POST[$key]??''));$input['kategorie_id']=(int)($_POST['kategorie_id']??0);$input['freigabe']=(string)($_POST['freigabe']??'privat');$input['dauer_minuten']=(string)($_POST['dauer_minuten']??'');
$categoryName='';if($input['kategorie_id']>0){$categoryQuery=$db->prepare('SELECT name FROM coaching_format_kategorien WHERE id=:id');$categoryQuery->execute(['id'=>$input['kategorie_id']]);$categoryName=(string)($categoryQuery->fetchColumn()?:'');}
$shareRaw=$_POST['freigabe_an']??[];$shareIds=is_array($shareRaw)?array_values(array_unique(array_filter(array_map('intval',$shareRaw),static fn(int $v):bool=>$v>0))):[];$selected=$shareIds;
if($input['titel']===''||strlen($input['titel'])>190||($input['kategorie_id']>0&&$categoryName==='')||strlen($input['kurzbeschreibung'])>1000||strlen($input['tags'])>500||!array_key_exists($input['freigabe'],$visibility))$error='Bitte fülle mindestens den Titel aus und prüfe die Feldlängen.';
elseif($input['ablauf']==='')$error='Bitte beschreibe den Ablauf des Formats.';
elseif($input['dauer_minuten']!==''&&((int)$input['dauer_minuten']<1||(int)$input['dauer_minuten']>600))$error='Die Dauer muss zwischen 1 und 600 Minuten liegen.';
elseif($input['freigabe']==='ausgewaehlte_coaches'&&$shareIds===[])$error='Wähle mindestens einen Coach für die Freigabe aus.';
else{try{$db->beginTransaction();$dur=$input['dauer_minuten']===''?null:(int)$input['dauer_minuten'];
if($id>0){$s=$db->prepare('UPDATE coaching_formate SET titel=:titel,kategorie=:kategorie,kategorie_id=:kategorie_id,kurzbeschreibung=:kurz,ziel=:ziel,ablauf=:ablauf,dauer_minuten=:dauer,materialien=:materialien,hinweise=:hinweise,quellen=:quellen,tags=:tags,freigabe=:freigabe WHERE id=:id AND coach_benutzer_id=:owner');$s->execute(['titel'=>$input['titel'],'kategorie'=>$categoryName,'kategorie_id'=>$input['kategorie_id']>0?$input['kategorie_id']:null,'kurz'=>$input['kurzbeschreibung'],'ziel'=>$input['ziel']?:null,'ablauf'=>$input['ablauf'],'dauer'=>$dur,'materialien'=>$input['materialien']?:null,'hinweise'=>$input['hinweise']?:null,'quellen'=>$input['quellen']?:null,'tags'=>$input['tags'],'freigabe'=>$input['freigabe'],'id'=>$id,'owner'=>$coach]);if($s->rowCount()===0){$check=$db->prepare('SELECT id FROM coaching_formate WHERE id=:id AND coach_benutzer_id=:owner');$check->execute(['id'=>$id,'owner'=>$coach]);if(!$check->fetchColumn())throw new RuntimeException('Format nicht gefunden.');}}
else{$s=$db->prepare('INSERT INTO coaching_formate (coach_benutzer_id,titel,kategorie,kategorie_id,kurzbeschreibung,ziel,ablauf,dauer_minuten,materialien,hinweise,quellen,tags,freigabe) VALUES (:owner,:titel,:kategorie,:kategorie_id,:kurz,:ziel,:ablauf,:dauer,:materialien,:hinweise,:quellen,:tags,:freigabe)');$s->execute(['owner'=>$coach,'titel'=>$input['titel'],'kategorie'=>$categoryName,'kategorie_id'=>$input['kategorie_id']>0?$input['kategorie_id']:null,'kurz'=>$input['kurzbeschreibung'],'ziel'=>$input['ziel']?:null,'ablauf'=>$input['ablauf'],'dauer'=>$dur,'materialien'=>$input['materialien']?:null,'hinweise'=>$input['hinweise']?:null,'quellen'=>$input['quellen']?:null,'tags'=>$input['tags'],'freigabe'=>$input['freigabe']]);$id=(int)$db->lastInsertId();}
$db->prepare('DELETE FROM coaching_format_freigaben WHERE format_id=:id')->execute(['id'=>$id]);
if($input['freigabe']==='ausgewaehlte_coaches'){$valid=$db->prepare("SELECT COUNT(*) FROM benutzer WHERE aktiv=1 AND rolle='coach' AND id=:coach");$insert=$db->prepare('INSERT INTO coaching_format_freigaben (format_id,coach_benutzer_id) VALUES (:format,:coach)');foreach($shareIds as $recipient){if($recipient===$coach)continue;$valid->execute(['coach'=>$recipient]);if((int)$valid->fetchColumn()!==1)throw new RuntimeException('Mindestens eine ausgewählte Person ist kein aktiver Coach.');$insert->execute(['format'=>$id,'coach'=>$recipient]);}}
$db->commit();header('Location: formats.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Format konnte nicht gespeichert werden. Bitte Migration 009 und Tabellenrechte prüfen.';error_log('Coaching formats save failed: '.$e->getMessage());$values=array_merge($values,$input);$values['id']=$id;}}
}

$search=trim((string)($_GET['q']??''));$categoryFilter=trim((string)($_GET['category']??''));if($categoryFilter!==''&&!ctype_digit($categoryFilter))$categoryFilter='';$sql='SELECT DISTINCT f.*,COALESCE(k.name,f.kategorie) AS kategorie_anzeige,b.vorname AS autor_vorname,b.nachname AS autor_nachname FROM coaching_formate f LEFT JOIN coaching_format_kategorien k ON k.id=f.kategorie_id INNER JOIN benutzer b ON b.id=f.coach_benutzer_id WHERE (f.coach_benutzer_id=:owner OR f.freigabe=\'alle_coaches\' OR EXISTS (SELECT 1 FROM coaching_format_freigaben a WHERE a.format_id=f.id AND a.coach_benutzer_id=:viewer))';$params=['owner'=>$coach,'viewer'=>$coach];
if($search!==''){$sql.=' AND (f.titel LIKE :title_q OR k.name LIKE :category_q OR f.kategorie LIKE :category_legacy_q OR f.kurzbeschreibung LIKE :desc_q OR f.ziel LIKE :goal_q OR f.ablauf LIKE :steps_q OR f.materialien LIKE :materials_q OR f.hinweise LIKE :notes_q OR f.quellen LIKE :source_q OR f.tags LIKE :tags_q)';$like='%'.$search.'%';foreach(['title_q','category_q','category_legacy_q','desc_q','goal_q','steps_q','materials_q','notes_q','source_q','tags_q'] as $key)$params[$key]=$like;}
if($categoryFilter!==''){$sql.=' AND f.kategorie_id=:category_filter';$params['category_filter']=(int)$categoryFilter;}
$sql.=' ORDER BY CASE WHEN f.coach_benutzer_id=:owner_order THEN 0 ELSE 1 END, f.kategorie,f.titel LIMIT 200';$params['owner_order']=$coach;$q=$db->prepare($sql);$q->execute($params);$entries=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<?php $showForm=isset($_GET['new'])||isset($_GET['edit'])||($_SERVER['REQUEST_METHOD']==='POST'&&$error!==''); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wissensdatenbank</title><link rel="stylesheet" href="assets/layout.css"><style>
.page{max-width:1200px;margin:auto;padding:34px clamp(24px,4vw,58px) 62px}
.toolbar{display:flex;gap:10px;align-items:center;margin:22px 0}.search{display:flex;gap:8px;flex:1}.search input,.search select{min-width:0;padding:11px 13px;border:1px solid #dce5df;border-radius:8px;font:inherit}.search input{flex:1}
.button{display:inline-flex;align-items:center;justify-content:center;background:#245c50;color:white;border:0;border-radius:8px;padding:11px 15px;font:inherit;text-decoration:none;cursor:pointer}.button.secondary{background:#edf5ef;color:#245c50}
.form-card,.entry{background:white;border:1px solid #e4ebe6;border-radius:14px;padding:20px;margin:14px 0}.form{display:grid;gap:10px}.form input,.form select,.form textarea{width:100%;padding:10px;border:1px solid #dce5df;border-radius:8px;font:inherit}.form textarea{min-height:90px;resize:vertical}
.meta{color:#6d7b74;font-size:13px}.entry h2{margin:6px 0}.entry p{margin:8px 0}.entry details{margin-top:12px}.entry summary{cursor:pointer;color:#245c50;font-weight:600}.entry-content{white-space:pre-wrap;line-height:1.6;margin:8px 0 14px}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1}.coach-picks{max-height:170px;overflow:auto;border:1px solid #e4ebe6;padding:10px;border-radius:8px}.coach-picks label{display:block;padding:5px}.empty{padding:24px;background:#f6f9f7;border-radius:12px}
@media(max-width:700px){.toolbar{align-items:stretch;flex-direction:column}.search{width:100%}.toolbar .button{width:100%}}
</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'formats',$token);?><main class="page">
<h1>Wissensdatenbank</h1><p>Eine interne Wissenssammlung für Coaching-Methoden und Anwendungen. Teile hier nur fachliche Inhalte, keine identifizierenden Klientendaten.</p>
<?php if($notice):?><p class="notice"><?=formatH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=formatH($error)?></p><?php endif;?>
<div class="toolbar"><form class="search" method="get"><input name="q" value="<?=formatH($search)?>" placeholder="Titel, Ablauf oder Schlagwort suchen" aria-label="Wissensdatenbank durchsuchen"><select name="category" aria-label="Kategorie filtern"><option value="">Alle Kategorien</option><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>" <?=$categoryFilter===(string)$category['id']?'selected':''?>><?=formatH($category['name'])?></option><?php endforeach;?></select><button class="button" type="submit">Suchen</button><?php if($search!==''||$categoryFilter!==''):?><a class="button secondary" href="formats.php">Filter zurücksetzen</a><?php endif;?></form><a class="button" href="formats.php?new=1">+ Neues Format hinzufügen</a></div>
<?php if($showForm): ?><section class="form-card"><h2><?=!empty($values['id'])?'Eigenes Format bearbeiten':'Neues Format hinzufügen'?></h2><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=formatH($token)?>"><input type="hidden" name="id" value="<?=(int)$values['id']?>"><label>Titel<input name="titel" maxlength="190" required value="<?=formatH($values['titel'])?>"></label><label>Kategorie<select name="kategorie_id"><option value="0">Ohne Kategorie</option><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>" <?=(int)($values['kategorie_id']??0)===(int)$category['id']?'selected':''?>><?=formatH($category['name'])?></option><?php endforeach;?></select></label><label>Kurzbeschreibung<input name="kurzbeschreibung" maxlength="1000" value="<?=formatH($values['kurzbeschreibung'])?>"></label><label>Ziel / Einsatzbereich<textarea name="ziel"><?=formatH($values['ziel']??'')?></textarea></label><label>Ablauf in Schritten<textarea name="ablauf" required><?=formatH($values['ablauf'])?></textarea></label><label>Dauer in Minuten<input type="number" min="1" max="600" name="dauer_minuten" value="<?=formatH($values['dauer_minuten']??'')?>"></label><label>Materialien<textarea name="materialien"><?=formatH($values['materialien']??'')?></textarea></label><label>Hinweise / Grenzen<textarea name="hinweise"><?=formatH($values['hinweise']??'')?></textarea></label><label>Quellen / Literatur<textarea name="quellen"><?=formatH($values['quellen']??'')?></textarea></label><label>Schlagwörter<input name="tags" maxlength="500" value="<?=formatH($values['tags'])?>" placeholder="Komma-getrennt"></label><label>Freigabe<select name="freigabe"><?php foreach($visibility as $key=>$label):?><option value="<?=formatH($key)?>" <?=$values['freigabe']===$key?'selected':''?>><?=formatH($label)?></option><?php endforeach;?></select></label><div class="meta">Nur bei Freigabe „Ausgewählte Coaches“ wirksam. Diese Coaches können den Eintrag lesen, aber nicht ändern.</div><div class="coach-picks"><?php foreach($coaches as $person):if((int)$person['id']===$coach)continue;?><label><input type="checkbox" name="freigabe_an[]" value="<?=(int)$person['id']?>" <?=in_array((int)$person['id'],$selected,true)?'checked':''?>> <?=formatH($person['vorname'].' '.$person['nachname'])?></label><?php endforeach;?></div><div><button class="button" type="submit">Format speichern</button> <a class="button secondary" href="formats.php">Zurück zur Liste</a></div></form></section>
<?php else: ?><section aria-labelledby="library-title"><h2 id="library-title">Formate (<?=count($entries)?><?=count($entries)===200?'+':''?>)</h2><?php if(!$entries):?><div class="empty">Keine passenden Formate gefunden. Passe den Suchbegriff an oder füge ein neues Format hinzu.</div><?php else:foreach($entries as $f):?><article class="entry"><div class="meta"><?=formatH($f['kategorie_anzeige']?:'Ohne Kategorie')?> · <?=formatH($f['autor_vorname'].' '.$f['autor_nachname'])?> · <?=((int)$f['coach_benutzer_id']===$coach?'Eigener Eintrag':($f['freigabe']==='alle_coaches'?'Mit allen Coaches geteilt':'Mit dir geteilt'))?></div><h2><?=formatH($f['titel'])?></h2><?php if($f['kurzbeschreibung']):?><p><?=formatH($f['kurzbeschreibung'])?></p><?php endif;?><?php if($f['tags']):?><p class="meta">Schlagwörter: <?=formatH($f['tags'])?></p><?php endif;?><details><summary>Details und Ablauf anzeigen</summary><?php if($f['ziel']):?><h3>Ziel / Einsatzbereich</h3><div class="entry-content"><?=formatH($f['ziel'])?></div><?php endif;?><h3>Ablauf</h3><div class="entry-content"><?=formatH($f['ablauf'])?></div><?php if($f['dauer_minuten']):?><p><strong>Dauer:</strong> <?=formatH($f['dauer_minuten'])?> Min.</p><?php endif;?><?php if($f['materialien']):?><h3>Materialien</h3><div class="entry-content"><?=formatH($f['materialien'])?></div><?php endif;?><?php if($f['hinweise']):?><h3>Hinweise / Grenzen</h3><div class="entry-content"><?=formatH($f['hinweise'])?></div><?php endif;?><?php if($f['quellen']):?><h3>Quellen / Literatur</h3><div class="entry-content"><?=formatH($f['quellen'])?></div><?php endif;?></details><?php if((int)$f['coach_benutzer_id']===$coach):?><p><a href="formats.php?edit=<?=(int)$f['id']?>">Eigenen Eintrag bearbeiten</a></p><?php endif;?></article><?php endforeach;endif;?></section><?php endif;?>
</main></body></html>